renderCharacterCards();$('#thumb1').innerHTML=thumbSvg(false);$('#thumb2').innerHTML=thumbSvg(true);renderScene();

let toastTimer;
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
function updateCount(){const n=$('#prompt').value.length;$('#charCount').textContent=`${n} / 500`}
$('#prompt').addEventListener('input',updateCount);updateCount();
$('#durationChoices').addEventListener('click',e=>{const b=e.target.closest('button[data-duration]');if(!b)return;duration=+b.dataset.duration;$$('#durationChoices button').forEach(x=>x.classList.toggle('selected',x===b));$('#timecode').textContent=`00:00 / 00:${String(duration).padStart(2,'0')}`});
$$('.style-card').forEach(b=>b.onclick=()=>{selectedStyle=b.dataset.style;$$('.style-card').forEach(x=>x.classList.toggle('selected',x===b));renderScene()});
$('#speedRange').oninput=e=>$('#speedValue').textContent=e.target.value;
$('#likeBtn').onclick=()=>{liked=!liked;$('#likeBtn').classList.toggle('liked',liked);$('#likeBtn').innerHTML=liked?'♥ &nbsp;Liked':'♡ &nbsp;Like';$('#likeCount').textContent=`${liked?129:128} likes`};
$('#commentBtn').onclick=()=>{$('#commentBox').classList.toggle('open');if($('#commentBox').classList.contains('open'))$('#commentInput').focus()};
$('#postComment').onclick=()=>{const v=$('#commentInput').value.trim();if(!v){toast('Write a comment first');return}const item=document.createElement('div');item.textContent='You: '+v;$('#commentsList').append(item);$('#commentInput').value='';toast('Comment posted')};
$('#commentInput').addEventListener('keydown',e=>{if(e.key==='Enter')$('#postComment').click()});
$('#remixBtn').onclick=()=>{$('#prompt').value=$('#prompt').value.replace(/[.!?\s]+$/,'')+' with a surprising twist';updateCount();toast('Remix started — make it your own!');window.scrollTo({top:0,behavior:'smooth'})};
$$('.nav button').forEach(b=>b.onclick=()=>{if(b.dataset.nav==='My videos')openGallery();else if(b.dataset.nav==='Explore')toast('Explore is coming soon — your studio is ready!');else window.scrollTo({top:0,behavior:'smooth'})});
$('#mobileMenu').onclick=()=>toast('Use the character and style panel below the editor.');
$('#muteBtn').onclick=()=>{$('#muteBtn').textContent=$('#muteBtn').textContent.includes('on')?'♫  Sound off':'♫  Sound on';toast('Preview audio preference updated')};
$('#playBtn').onclick=()=>{playing=!playing;$('#playBtn').textContent=playing?'Ⅱ':'▶';if(playing){$('#previewState').textContent='PREVIEW PLAYING';$('#progressFill').style.animation=`previewProgress ${duration}s linear infinite`;setTimeout(()=>{if(playing){playing=false;$('#playBtn').textContent='▶';$('#previewState').textContent=generated?'ANIMATION READY':'READY TO CREATE';$('#progressFill').style.animation='none'}},duration*1000)}else{$('#previewState').textContent=generated?'ANIMATION READY':'READY TO CREATE';$('#progressFill').style.animation='none'}};
$('#expandBtn').onclick=()=>{const p=$('#preview');if(p.requestFullscreen)p.requestFullscreen();else toast('Fullscreen is not supported in this browser')};
let galleryEntry=null;
function saveToGallery(){galleryEntry={title:$('#captionTitle').textContent,style:selectedStyle,duration,created:new Date().toLocaleString(),svg:$('#sceneSvg').outerHTML,blob:recordedBlob};openGallery()}
$('#openGallery').onclick=()=>openGallery();$('#closeGallery').onclick=()=>$('#galleryModal').classList.remove('open');$('#galleryModal').onclick=e=>{if(e.target===$('#galleryModal'))$('#galleryModal').classList.remove('open')};
function openGallery(){const box=$('#galleryContent');if(!galleryEntry){box.innerHTML='<div class="gallery-empty"><span>▣</span>Your finished animations will show up here.<br><small>Generate your first video to get started.</small></div>'}else{box.innerHTML=`<div class="gallery-item"><div class="gallery-thumb">${galleryEntry.svg}</div><div><div class="gallery-item-title">${escapeHtml(galleryEntry.title)}</div><div class="gallery-item-meta">${galleryEntry.duration}s · ${escapeHtml(galleryEntry.style)} · ${galleryEntry.created}</div></div><button id="galleryDownload">⇩ &nbsp;Download</button></div>`;$('#galleryDownload').onclick=downloadVideo}$('#galleryModal').classList.add('open')}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function drawExportFrame(ctx,t){const w=960,h=540;let sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,selectedStyle==='Modern 2D'?'#f9dca1':'#a9d8ec');sky.addColorStop(1,'#e8f4e3');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);ctx.fillStyle='#ffe17b';ctx.beginPath();ctx.arc(790,95,47,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';[[175,106,55,18],[210,98,35,19],[695,168,45,14],[724,159,30,17]].forEach(([x,y,rx,ry])=>{ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()});ctx.fillStyle='#9dd69b';ctx.beginPath();ctx.moveTo(0,330);ctx.quadraticCurveTo(180,258,350,326);ctx.quadraticCurveTo(690,280,960,318);ctx.lineTo(960,540);ctx.lineTo(0,540);ctx.fill();ctx.fillStyle='#71bd7d';ctx.beginPath();ctx.moveTo(0,386);ctx.quadraticCurveTo(190,320,390,390);ctx.quadraticCurveTo(760,350,960,380);ctx.lineTo(960,540);ctx.lineTo(0,540);ctx.fill();let cast=selectedCharacters.slice(0,3).map(i=>characters[i]);if(!cast.length)cast=[characters[0]];const positions=cast.length===1?[480]:cast.length===2?[410,550]:[340,480,620];cast.forEach((c,i)=>drawPig(ctx,c,positions[i],335+(i===1?0:8)+Math.sin(t*5+i)*7,c.kind==='daddy'?1.35:1.08));ctx.font='25px Arial';ctx.textAlign='center';ctx.fillStyle='#fff';ctx.fillText('A little adventure awaits',480,76);for(const [x,y] of [[160,410],[804,389],[270,460],[700,447]]){ctx.fillStyle='#fff08a';for(let j=0;j<5;j++){let a=j*Math.PI*2/5;ctx.beginPath();ctx.arc(x+Math.cos(a)*7,y+Math.sin(a)*7,4,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#ffbc4c';ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill()}}
function drawPig(ctx,c,x,y,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='rgba(40,70,50,.16)';ctx.beginPath();ctx.ellipse(0,65,41,9,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=c.dress;ctx.beginPath();if(c.kind==='daddy')ctx.ellipse(0,24,31,34,0,0,Math.PI*2);else{ctx.moveTo(-26,61);ctx.quadraticCurveTo(-31,5,0,4);ctx.quadraticCurveTo(30,8,26,61);ctx.closePath()}ctx.fill();ctx.strokeStyle='#d58b7a';ctx.lineWidth=5;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-11,53);ctx.lineTo(-11,67);ctx.moveTo(12,53);ctx.lineTo(12,67);ctx.stroke();ctx.strokeStyle='#5d4c48';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-17,68);ctx.lineTo(-7,68);ctx.moveTo(6,68);ctx.lineTo(17,68);ctx.stroke();ctx.fillStyle=c.color;ctx.beginPath();ctx.ellipse(-12,-25,7,13,-.2,0,Math.PI*2);ctx.ellipse(9,-26,7,13,.2,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(0,0,29,0,Math.PI*2);ctx.fill();ctx.fillStyle=c.color;ctx.beginPath();ctx.ellipse(23,1,16,10,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#c66572';ctx.beginPath();ctx.arc(20,0,2,0,Math.PI*2);ctx.arc(27,0,2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#26333b';ctx.beginPath();ctx.ellipse(-5,-8,3,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='white';ctx.beginPath();ctx.arc(-6,-10,1.3,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ac5962';ctx.lineWidth=2;ctx.beginPath();ctx.arc(2,7,9,.2,1.8);ctx.stroke();if(c.kind==='daddy'){ctx.strokeStyle='#344b58';ctx.lineWidth=2;ctx.beginPath();ctx.arc(-8,-8,9,0,Math.PI*2);ctx.arc(7,-8,9,0,Math.PI*2);ctx.moveTo(1,-8);ctx.lineTo(-2,-8);ctx.stroke()}ctx.restore()}
function recordVideo(){return new Promise((resolve,reject)=>{const canvas=document.createElement('canvas');canvas.width=960;canvas.height=540;const ctx=canvas.getContext('2d');const stream=canvas.captureStream(30);let mime=['video/mp4;codecs=h264','video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime){reject(new Error('Video export is not supported in this browser.'));return}let rec;try{rec=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:3500000})}catch(err){reject(err);return}let chunks=[];rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};rec.onerror=()=>reject(new Error('The video could not be exported.'));rec.onstop=()=>{stream.getTracks().forEach(t=>t.stop());resolve(new Blob(chunks,{type:mime.split(';')[0]}))};let start=performance.now();const draw=now=>{let elapsed=(now-start)/1000;drawExportFrame(ctx,elapsed);if(elapsed<duration)requestAnimationFrame(draw);else rec.stop()};drawExportFrame(ctx,0);rec.start();requestAnimationFrame(draw)})}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
async function downloadVideo(){if(!generated){toast('Generate your animation first');return}if(recordedBlob){downloadBlob(recordedBlob,`sora-studio-${Date.now()}.${recordedBlob.type.includes('mp4')?'mp4':'webm'}`);toast(`Video downloaded as ${recordedBlob.type.includes('mp4')?'MP4':'WebM'}`);return}$('#downloadBtn').disabled=true;$('#downloadBtn').textContent='◌  Rendering…';toast(`Rendering ${duration}-second video…`);try{recordedBlob=await recordVideo();galleryEntry={title:$('#captionTitle').textContent,style:selectedStyle,duration,created:new Date().toLocaleString(),svg:$('#sceneSvg').outerHTML,blob:recordedBlob};downloadBlob(recordedBlob,`sora-studio-${Date.now()}.${recordedBlob.type.includes('mp4')?'mp4':'webm'}`);toast(`Saved video · ${recordedBlob.type.includes('mp4')?'MP4':'WebM'} format`)}catch(e){toast(e.message||'Could not export video')}finally{$('#downloadBtn').disabled=false;$('#downloadBtn').textContent='⇩  Download'}}
$('#downloadBtn').onclick=downloadVideo;
$('#generateBtn').onclick=()=>{if(isGenerating)return;isGenerating=true;generated=false;recordedBlob=null;$('#generateBtn').disabled=true;$('#generateBtn').textContent='◌  Creating…';$('#previewState').textContent='DREAMING UP YOUR SCENE';$('#playBtn').style.display='none';$('#generationStatus').innerHTML='<span class="spinner"></span> &nbsp;Warming up the imagination…';let started=Date.now(),wait=Math.max(1600,7400-(+$('#speedRange').value)*56);const timer=setInterval(()=>{let p=Math.min(100,Math.round((Date.now()-started)/wait*100));$('#generationStatus').innerHTML=`<span class="spinner"></span> &nbsp;Creating your animation… ${p}%`;$('#progressFill').style.width=p+'%';if(p>=100){clearInterval(timer);isGenerating=false;generated=true;$('#generateBtn').disabled=false;$('#generateBtn').textContent='✦  Generate again';$('#playBtn').style.display='grid';$('#previewState').textContent='ANIMATION READY';$('#generationStatus').innerHTML='✓ &nbsp;Your animation is ready! Save it to your gallery or download it.';$('#progressFill').style.width='32%';const words=$('#prompt').value.trim().split(/\s+/).slice(0,7).join(' ');if(words)$('#captionTitle').textContent=words+(words.length<42?'':'…');galleryEntry={title:$('#captionTitle').textContent,style:selectedStyle,duration,created:new Date().toLocaleString(),svg:$('#sceneSvg').outerHTML,blob:null};toast('Your animation is ready!')}} ,100)};
</script>
</body>
</html>

